/**
 * Thin HTTP client for the Imference API (https://imference.com/docs).
 *
 * Credits rail (Bearer API key):
 *   GET  /api/models          public model catalog
 *   GET  /api/formats         per-model formats (resolution/ratio)
 *   POST /generate            submit a generation (image or video, model-driven)
 *   GET  /credits/balance     remaining credits for the API key
 *   GET  /media/all           all media generated by the API key
 *
 * x402 rail (USDC on Base, signed with a wallet private key):
 *   POST /ondemand/generate      pay-per-generation at the model's catalog price
 *   POST /ondemand/credits/add   prepay credits onto an API key (min 100, max 1M)
 *
 * Status polling uses GET /ondemand/status — the shared, unauthenticated status
 * handler that serves requests from BOTH rails (404 = pending, 422 = failed,
 * 200 = done).
 */

import { createSigner, decodeXPaymentResponse, wrapFetchWithPayment } from "x402-fetch";
import { privateKeyToAccount } from "viem/accounts";
import { createPublicClient, erc20Abi, formatUnits, http } from "viem";
import { base } from "viem/chains";
import type { Hex } from "viem";

/** USDC contract on Base mainnet. */
const USDC_BASE = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913" as const;

export interface ImferenceConfig {
  baseUrl: string;
  apiKey?: string;
  /** EVM private key (0x-prefixed, 64 hex chars) holding USDC on Base for x402 payments. */
  walletPrivateKey?: string;
  /** Hard cap in USD on any single x402 payment, whatever the tool call asks for. */
  x402MaxUsdPerCall?: number;
  /** Cumulative cap in USD on x402 spend over this server process's lifetime. */
  x402SessionMaxUsd?: number;
  /** Base mainnet RPC URL for balance reads (default https://mainnet.base.org). */
  baseRpcUrl?: string;
}

export interface ImModel {
  model_code: string;
  name?: string;
  description?: string;
  short_description?: string;
  medium_description?: string;
  image?: string;
  model_url?: string;
  prompt_pre?: string;
  prompt_negative?: string;
  steps_default: number;
  steps_min: number;
  steps_max: number;
  cfg_default: number;
  cfg_min: number;
  cfg_max: number;
  skip_default: number;
  skip_min: number;
  skip_max: number;
  scheduler_default?: string;
  queue?: string;
  format_code?: string;
  im_engine?: string;
  frames_default?: number;
  frames_min?: number;
  frames_max?: number;
  fps_default?: number;
  fps_min?: number;
  fps_max?: number;
  im_cost: number;
  duration_s_default?: number | null;
  duration_s_min?: number | null;
  duration_s_max?: number | null;
  /** "image" | "video" — authoritative media kind from the catalog. */
  model_type?: string;
  family_name?: string;
  /** "tags" (booru-style comma-separated tags) or "natural" (plain sentences). */
  family_prompt_style?: string;
  accepts_image_input?: boolean | null;
  image_input_max?: number | null;
  has_audio?: boolean | null;
  /**
   * Per-model parameter schema published by the API — the exact list
   * ValidateParams enforces, so it cannot drift from what a request may send.
   */
  parameters?: unknown[];
  [key: string]: unknown;
}

export interface ImFormat {
  model_code: string;
  format_code: string;
  name?: string;
  width: number;
  height: number;
  ratio?: string;
  description?: string;
  order: number;
  is_default: boolean;
  /** Price multiplier of this format (1 when absent; HD tiers typically bill ×2). */
  credit_multiplier?: number | null;
}

/** /status and /media/all rows marshal Go struct fields verbatim (untagged). */
export interface MediaRow {
  RequestID: string;
  Kind: string;
  URL: string;
  Format: string;
  Seed: number;
  Timestamp: string;
}

/**
 * Wire payload for POST /generate and /ondemand/generate.
 *
 * Output size is selected with format_code (a predefined format from
 * /api/formats, e.g. "landscape-wide") — never raw width/height: the API
 * translates the format into dimensions for the GPU workers, and the format
 * carries the price multiplier. Free-form knobs like aspect_ratio only exist
 * on externally-hosted models and are refused everywhere else, so this client
 * doesn't offer them.
 */
export interface GeneratePayload {
  model: string;
  prompt: string;
  negative_prompt?: string;
  steps?: number;
  clip_skip?: number;
  guidance_scale?: number;
  seed?: number;
  batch_nbr?: number;
  num_frames?: number;
  fps?: number;
  img_url?: string;
  scheduler?: string;
  format_code?: string;
  duration_s?: number;
}

export type StatusResult =
  | { state: "pending" }
  | { state: "failed"; error: string }
  | { state: "done"; media: MediaRow };

/** Settlement info decoded from the X-PAYMENT-RESPONSE header after an x402 payment. */
export interface PaymentReceipt {
  success?: boolean;
  transaction?: string;
  network?: string;
  payer?: string;
}

/** x402 credits top-up bounds (mirrors the API: min $0.10, max $1,000 per call). */
export const MIN_X402_CREDITS_TOPUP = 100;
export const MAX_X402_CREDITS_TOPUP = 1_000_000;

/** 1 credit = $0.001 = 1000 atomic USDC units (6 decimals). */
export function creditsToAtomicUsdc(credits: number): bigint {
  return BigInt(Math.ceil(credits)) * 1000n;
}

/** USD → atomic USDC units (6 decimals). */
export function usdToAtomic(usd: number): bigint {
  return BigInt(Math.round(usd * 1_000_000));
}

export function atomicToUsd(atomic: bigint): number {
  return Number(atomic) / 1_000_000;
}

export class ImferenceError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
  ) {
    super(message);
    this.name = "ImferenceError";
  }
}

export class ImferenceClient {
  /** Cumulative x402 spend this process, in atomic USDC units. */
  private sessionSpentAtomic = 0n;

  constructor(private readonly config: ImferenceConfig) {
    if (config.walletPrivateKey && !/^0x[0-9a-fA-F]{64}$/.test(config.walletPrivateKey)) {
      throw new ImferenceError(
        "IMFERENCE_WALLET_PRIVATE_KEY must be a 0x-prefixed 64-hex-char EVM private key",
      );
    }
  }

  get hasApiKey(): boolean {
    return !!this.config.apiKey;
  }

  get hasWallet(): boolean {
    return !!this.config.walletPrivateKey;
  }

  /** Public address of the configured wallet (never exposes the key). */
  get walletAddress(): string | undefined {
    if (!this.config.walletPrivateKey) return undefined;
    return privateKeyToAccount(this.config.walletPrivateKey as Hex).address;
  }

  get sessionSpentUsd(): number {
    return atomicToUsd(this.sessionSpentAtomic);
  }

  get spendingCaps(): { perCallUsd?: number; sessionMaxUsd?: number; sessionSpentUsd: number } {
    return {
      perCallUsd: this.config.x402MaxUsdPerCall,
      sessionMaxUsd: this.config.x402SessionMaxUsd,
      sessionSpentUsd: this.sessionSpentUsd,
    };
  }

  /**
   * Spending guard, enforced by this server regardless of what the tool call
   * asks for. Runs BEFORE any signing or network call.
   */
  private authorizeSpend(priceAtomic: bigint, label: string): void {
    const perCall = this.config.x402MaxUsdPerCall;
    if (perCall !== undefined && priceAtomic > usdToAtomic(perCall)) {
      throw new ImferenceError(
        `Payment blocked: ${label} costs $${atomicToUsd(priceAtomic).toFixed(3)}, above the ` +
          `per-call cap of $${perCall} (IMFERENCE_X402_MAX_USD). Raise the cap in the server ` +
          `environment if this spend is intended.`,
      );
    }
    const sessionMax = this.config.x402SessionMaxUsd;
    if (sessionMax !== undefined && this.sessionSpentAtomic + priceAtomic > usdToAtomic(sessionMax)) {
      throw new ImferenceError(
        `Payment blocked: ${label} ($${atomicToUsd(priceAtomic).toFixed(3)}) would push session ` +
          `spend past $${sessionMax} (IMFERENCE_X402_SESSION_MAX_USD; already spent ` +
          `$${this.sessionSpentUsd.toFixed(3)}). Restart the server or raise the cap to continue.`,
      );
    }
  }

  /**
   * fetch wrapped with the x402 payment flow: on a 402 challenge, signs an
   * EIP-3009 USDC transfer (Base mainnet) with the configured wallet and
   * retries with the X-PAYMENT header. maxAtomic caps what the wallet will
   * sign for, in atomic USDC units (6 decimals).
   */
  private async paymentFetch(maxAtomic: bigint): Promise<typeof fetch> {
    if (!this.config.walletPrivateKey) {
      throw new ImferenceError(
        "IMFERENCE_WALLET_PRIVATE_KEY is not set. The x402 rail needs an EVM wallet " +
          "holding USDC on Base to sign payments.",
      );
    }
    const signer = await createSigner("base", this.config.walletPrivateKey as Hex);
    return wrapFetchWithPayment(fetch, signer, maxAtomic) as typeof fetch;
  }

  private receipt(res: Response): PaymentReceipt | undefined {
    const header = res.headers.get("x-payment-response");
    if (!header) return undefined;
    try {
      return decodeXPaymentResponse(header) as PaymentReceipt;
    } catch {
      return undefined;
    }
  }

  private headers(auth: boolean): Record<string, string> {
    const h: Record<string, string> = { "Content-Type": "application/json" };
    if (auth) {
      if (!this.config.apiKey) {
        throw new ImferenceError(
          "IMFERENCE_API_KEY is not set. This tool requires an Imference API key " +
            "(get one and add credits at https://imference.com).",
        );
      }
      h["Authorization"] = `Bearer ${this.config.apiKey}`;
    }
    return h;
  }

  private url(path: string, query?: Record<string, string>): string {
    const u = new URL(path, this.config.baseUrl);
    for (const [k, v] of Object.entries(query ?? {})) u.searchParams.set(k, v);
    return u.toString();
  }

  /**
   * GET with 2 retries on network errors, 5xx and 529 (backoff 500ms/1500ms).
   * Only used for idempotent reads — POSTs (which charge) are never retried.
   */
  private async getWithRetry(url: string, headers: Record<string, string>): Promise<Response> {
    const delays = [500, 1500];
    for (let attempt = 0; ; attempt++) {
      try {
        const res = await fetch(url, { headers });
        if (res.status < 500 || attempt >= delays.length) return res;
      } catch (err) {
        if (attempt >= delays.length) throw err;
      }
      await new Promise((r) => setTimeout(r, delays[attempt]));
    }
  }

  private async parseError(res: Response): Promise<string> {
    try {
      const body = (await res.json()) as { error?: string };
      return body.error ?? `HTTP ${res.status}`;
    } catch {
      return `HTTP ${res.status}`;
    }
  }

  async listModels(): Promise<ImModel[]> {
    const res = await this.getWithRetry(this.url("/api/models"), this.headers(false));
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    const body = (await res.json()) as { models: ImModel[] };
    return body.models ?? [];
  }

  async listFormats(): Promise<ImFormat[]> {
    const res = await this.getWithRetry(this.url("/api/formats"), this.headers(false));
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    const body = (await res.json()) as { formats: ImFormat[] };
    return body.formats ?? [];
  }

  async generate(payload: GeneratePayload): Promise<{ request_id: string; kind: string }> {
    const res = await fetch(this.url("/generate"), {
      method: "POST",
      headers: this.headers(true),
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    return (await res.json()) as { request_id: string; kind: string };
  }

  /**
   * One status probe via the shared unauthenticated handler (serves both
   * rails). The API maps request state to HTTP codes:
   * 404 → still pending (or unknown id), 422 → generation failed, 200 → done.
   */
  async status(requestId: string): Promise<StatusResult> {
    const res = await this.getWithRetry(this.url("/ondemand/status", { request_id: requestId }), this.headers(false));
    if (res.status === 404) return { state: "pending" };
    if (res.status === 422) return { state: "failed", error: await this.parseError(res) };
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    const body = (await res.json()) as { data: MediaRow };
    return { state: "done", media: body.data };
  }

  async balance(): Promise<number> {
    const res = await this.getWithRetry(this.url("/credits/balance"), this.headers(true));
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    const body = (await res.json()) as { credits: number };
    return body.credits;
  }

  /**
   * Pay-per-generation via x402: POST /ondemand/generate. The server prices
   * the 402 challenge at the model's catalog cost — pass that cost so the
   * spending guards run against it and the wallet signs for exactly that
   * amount (+ $0.01 headroom for rounding).
   */
  async generateX402(
    payload: GeneratePayload,
    priceCredits: number,
  ): Promise<{ request_id: string; kind: string; payment?: PaymentReceipt }> {
    const priceAtomic = creditsToAtomicUsdc(priceCredits);
    this.authorizeSpend(priceAtomic, `generation with model '${payload.model}'`);
    const payFetch = await this.paymentFetch(priceAtomic + 10_000n);
    const res = await payFetch(this.url("/ondemand/generate"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    this.sessionSpentAtomic += priceAtomic;
    const body = (await res.json()) as { request_id: string; kind: string };
    return { ...body, payment: this.receipt(res) };
  }

  /**
   * Prepay credits onto an API key with one USDC payment (price = credits ×
   * $0.001). An empty apiKey makes the server mint and return a fresh key.
   */
  async addCreditsX402(
    credits: number,
    apiKey?: string,
  ): Promise<{ api_key: string; credits_added: number; payment?: PaymentReceipt }> {
    const priceAtomic = creditsToAtomicUsdc(credits);
    this.authorizeSpend(priceAtomic, `credits top-up of ${credits} credits`);
    const payFetch = await this.paymentFetch(priceAtomic + 10_000n);
    const res = await payFetch(this.url("/ondemand/credits/add"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ credits, ...(apiKey ? { api_key: apiKey } : {}) }),
    });
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    this.sessionSpentAtomic += priceAtomic;
    const body = (await res.json()) as { api_key: string; credits_added: number };
    return { ...body, payment: this.receipt(res) };
  }

  /**
   * Download a generated media file. Restricted to http(s); returns the raw
   * bytes plus the response content type.
   */
  async downloadMedia(url: string): Promise<{ bytes: Buffer; contentType: string }> {
    const u = new URL(url);
    if (u.protocol !== "https:" && u.protocol !== "http:") {
      throw new ImferenceError(`Unsupported URL scheme '${u.protocol}' — expected http(s)`);
    }
    const res = await this.getWithRetry(url, {});
    if (!res.ok) throw new ImferenceError(`Download failed: HTTP ${res.status}`, res.status);
    return {
      bytes: Buffer.from(await res.arrayBuffer()),
      contentType: res.headers.get("content-type") ?? "application/octet-stream",
    };
  }

  /** USDC balance of the configured wallet on Base mainnet (read-only RPC call). */
  async usdcBalance(): Promise<{ address: string; usdc: number }> {
    const address = this.walletAddress;
    if (!address) {
      throw new ImferenceError(
        "IMFERENCE_WALLET_PRIVATE_KEY is not set — no wallet to read a balance for.",
      );
    }
    const rpc = createPublicClient({
      chain: base,
      transport: http(this.config.baseRpcUrl ?? "https://mainnet.base.org"),
    });
    const raw = await rpc.readContract({
      address: USDC_BASE,
      abi: erc20Abi,
      functionName: "balanceOf",
      args: [address as Hex],
    });
    return { address, usdc: Number(formatUnits(raw, 6)) };
  }

  async allMedia(): Promise<MediaRow[]> {
    const res = await this.getWithRetry(this.url("/media/all"), this.headers(true));
    if (res.status === 204) return [];
    if (!res.ok) throw new ImferenceError(await this.parseError(res), res.status);
    const body = (await res.json()) as { data: MediaRow[] };
    return body.data ?? [];
  }
}

/**
 * The catalog's model_type is authoritative ("wan3-video" has a null engine and
 * would slip through the heuristic); the engine/queue check remains as fallback
 * for API builds that predate the field.
 */
export function isVideoModel(m: ImModel): boolean {
  if (m.model_type) return m.model_type === "video";
  return m.im_engine === "wan22" || (m.queue ?? "").startsWith("wan-video");
}

/**
 * What the API will charge for this request, in credits — mirrors the API's
 * creditCost (pricing.go), which prices BOTH rails:
 *
 *   cost = max(1, ceil(im_cost × format multiplier × duration multiplier × batch_nbr))
 *
 * with free (im_cost = 0) models staying free. The x402 402 challenge is priced
 * with this exact formula, so the wallet must sign for this amount — signing for
 * the bare im_cost fails as soon as a format bills ×2 or batch_nbr > 1.
 */
export function computeCreditCost(
  m: ImModel,
  format: ImFormat | undefined,
  p: Pick<GeneratePayload, "batch_nbr" | "duration_s">,
): number {
  if (m.im_cost <= 0) return 0;
  const fmtMult =
    format?.credit_multiplier && format.credit_multiplier > 0 ? format.credit_multiplier : 1;
  const batchMult = p.batch_nbr && p.batch_nbr > 1 ? p.batch_nbr : 1;
  const cost = m.im_cost * fmtMult * durationMultiplier(m, p.duration_s) * batchMult;
  return Math.max(1, Math.ceil(cost));
}

/** Requested clip length (clamped to the model's bounds) over the default length; 1 without duration control. */
function durationMultiplier(m: ImModel, durationS: number | undefined): number {
  const def = m.duration_s_default;
  if (def == null || def <= 0) return 1;
  let d = durationS ?? 0;
  if (d <= 0) return 1;
  if (m.duration_s_min != null && d < m.duration_s_min) d = m.duration_s_min;
  if (m.duration_s_max != null && d > m.duration_s_max) d = m.duration_s_max;
  return d / def;
}

/**
 * The format a request selects: its format_code when it names one, else the
 * model's default format. Same resolution the API prices with (resolveFormat).
 */
export function resolveFormat(
  formats: ImFormat[],
  formatCode: string | undefined,
): ImFormat | undefined {
  const code = formatCode?.trim().toLowerCase();
  if (code) {
    const hit = formats.find((f) => f.format_code.toLowerCase() === code);
    if (hit) return hit;
  }
  return formats.find((f) => f.is_default);
}
